<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN','VERIFICADOR']);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ausencias y reposiciones — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172033}.wrap{max-width:980px;margin:auto;padding:78px 12px 32px}h1{margin:0 0 4px}.sub{color:#64748b;font-size:13px;margin-bottom:16px}.context{display:none;background:#e8eef2;color:#334155;border-radius:12px;padding:10px 12px;margin-bottom:12px;font-size:12px;font-weight:800}.context.show{display:flex;justify-content:space-between;gap:10px;align-items:center}.context button{border:0;background:#fff;border-radius:8px;padding:6px 9px;font-weight:800;color:#334155}.card{background:#fff;border-radius:14px;padding:14px;margin-bottom:12px}.grid{display:grid;gap:10px}.field label{display:block;font-size:11px;font-weight:800;color:#64748b;margin-bottom:5px}.field input,.field select,.field textarea{width:100%;padding:10px 11px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;font-size:15px}.field textarea{min-height:70px}.btn{border:0;border-radius:9px;padding:10px 12px;font-weight:800;cursor:pointer}.btn-primary{background:#172033;color:#fff}.btn-danger{background:#fff1f2;color:#9f1239}.row{display:flex;justify-content:space-between;gap:10px;align-items:flex-start;padding:11px 0;border-bottom:1px solid #eef2f7}.row:last-child{border:0}.name{font-weight:800}.meta{font-size:12px;color:#64748b;margin-top:3px}.status{font-size:10px;font-weight:900;border-radius:999px;padding:4px 7px;background:#e8eef2}.section{margin-top:18px}.section h2{font-size:18px;margin:0 0 10px}.section.hidden{display:none}.empty{text-align:center;color:#64748b;padding:20px}.repo{display:flex;justify-content:space-between;align-items:center;padding:9px 0;border-bottom:1px solid #eef2f7}.repo:last-child{border:0}.count{font-size:18px;font-weight:900}@media(min-width:760px){.wrap{padding-top:35px}.grid{grid-template-columns:1.4fr 1fr 1fr}.field.full{grid-column:1/-1}}</style></head><body><main class="wrap"><h1>Ausencias y reposiciones</h1><div class="sub">Avisos anticipados y saldo disponible</div><div id="context" class="context"></div><section id="formSection" class="card"><div class="grid"><div class="field"><label>Alumno</label><select id="alumno"><option value="">Seleccionar…</option></select></div><div class="field"><label>Desde</label><input id="desde" type="date"></div><div class="field"><label>Hasta</label><input id="hasta" type="date"></div><div class="field full"><label>Motivo</label><textarea id="motivo" placeholder="Ej. viaje, vacaciones, cita médica…"></textarea></div></div><button id="guardar" class="btn btn-primary">Registrar aviso</button></section><section id="avisosSection" class="section"><h2>Avisos</h2><div id="avisos" class="card"><div class="empty">Cargando…</div></div></section><section id="reposSection" class="section"><h2>Reposiciones disponibles</h2><div id="repos" class="card"><div class="empty">Cargando…</div></div></section></main><script>const alumno=document.getElementById('alumno'),desde=document.getElementById('desde'),hasta=document.getElementById('hasta'),avisos=document.getElementById('avisos'),repos=document.getElementById('repos'),ctx=document.getElementById('context'),avisosSection=document.getElementById('avisosSection'),reposSection=document.getElementById('reposSection'),formSection=document.getElementById('formSection');function esc(v){const t=document.createElement('textarea');t.textContent=String(v??'');return t.innerHTML}let mode=new URLSearchParams(location.search).get('alerta')||'';const hoy=new Date().toISOString().slice(0,10);desde.value=hoy;hasta.value=hoy;function localISO(d){const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,10)}function mananaISO(){const d=new Date();d.setDate(d.getDate()+1);return localISO(d)}function aplicarContexto(){avisosSection.classList.toggle('hidden',mode==='reposiciones');reposSection.classList.toggle('hidden',mode==='manana');formSection.classList.toggle('hidden',!!mode);if(!mode){ctx.className='context';ctx.innerHTML='';return}ctx.className='context show';ctx.innerHTML=`<span>${mode==='manana'?'Mostrando solo avisos que aplican mañana':'Mostrando solo reposiciones disponibles'}</span><button type="button" id="clearContext">Ver todo</button>`;document.getElementById('clearContext').onclick=()=>{mode='';history.replaceState({},'',location.pathname);aplicarContexto();cargar()}}async function post(body){const r=await fetch('/api/ausencias-programadas.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}async function alumnos(){const r=await fetch('/api/alumnos.php'),d=await r.json();if(d.ok)(d.alumnos||[]).sort((a,b)=>(a.nombre||'').localeCompare(b.nombre||'','es')).forEach(a=>alumno.insertAdjacentHTML('beforeend',`<option value="${esc(a.id)}">${esc(a.nombre)}</option>`))}async function cargar(){const r=await fetch('/api/ausencias-programadas.php',{cache:'no-store'}),d=await r.json();if(!d.ok){avisos.innerHTML='<div class="empty">Error al cargar.</div>';return}let lista=d.avisos||[];if(mode==='manana'){const f=mananaISO();lista=lista.filter(x=>x.estado==='ACTIVO'&&x.fecha_desde<=f&&x.fecha_hasta>=f)}avisos.innerHTML=lista.length?lista.map(x=>`<div class="row"><div><div class="name">${esc(x.nombre)}</div><div class="meta">${esc(x.fecha_desde)}${x.fecha_hasta!==x.fecha_desde?' → '+esc(x.fecha_hasta):''}${x.motivo?' · '+esc(x.motivo):''}</div></div><div>${x.estado==='ACTIVO'?`<button class="btn btn-danger" data-cancel="${esc(x.id)}">Cancelar</button>`:`<span class="status">CANCELADO</span>`}</div></div>`).join(''):'<div class="empty">Sin avisos para este contexto.</div>';repos.innerHTML=d.reposiciones.length?d.reposiciones.map(x=>`<div class="repo"><span>${esc(x.nombre)}</span><span class="count">${esc(x.disponibles)}</span></div>`).join(''):'<div class="empty">No hay reposiciones disponibles.</div>'}document.getElementById('guardar').onclick=async()=>{if(!alumno.value)return alert('Selecciona un alumno');try{await post({accion:'CREAR',alumno_id:alumno.value,fecha_desde:desde.value,fecha_hasta:hasta.value,motivo:document.getElementById('motivo').value});document.getElementById('motivo').value='';cargar()}catch(e){alert(e.message)}};avisos.onclick=async e=>{const b=e.target.closest('[data-cancel]');if(!b)return;if(!confirm('¿Cancelar este aviso?'))return;try{await post({accion:'CANCELAR',id:b.dataset.cancel});cargar()}catch(err){alert(err.message)}};aplicarContexto();alumnos();cargar();</script></body></html>
